import{_ as t,c as i,o as n,b0 as l}from"./chunks/framework.CLL9SSSf.js";const r="/linux-driver-docs/assets/1531300792461.B0DltCG8.png",a="/linux-driver-docs/assets/image-20241224225509388.CXZKqx_-.png",f=JSON.parse('{"title":"LV10-VFS的四大对象","description":null,"frontmatter":{"title":"LV10-VFS的四大对象","date":"2026-01-13T20:35:38.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/vfs/vfs-fw/126d2cd9c1520aeddd87e1c8","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-01-13T20:35:38.174Z","fulluuid":"ddd87e1c8f8c4593b0ef9d022369465e","useduuid":"ddd87e1c8"}},"headers":[],"relativePath":"sdoc/vfs/vfs-fw/126d2cd9c1520aeddd87e1c8.md","filePath":"sdoc/10-虚拟文件系统/05-VFS框架/LV10-VFS的四大对象.md","lastUpdated":1769002717000}'),o={name:"sdoc/vfs/vfs-fw/126d2cd9c1520aeddd87e1c8.md"};function d(s,e,u,p,c,b){return n(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="lv10-vfs的四大对象" tabindex="-1">LV10-VFS的四大对象 <a class="header-anchor" href="#lv10-vfs的四大对象" aria-label="Permalink to &quot;LV10-VFS的四大对象&quot;">​</a></h1><p>前面已经大概了解过VFS虚拟文件系统了，这里主要是深入了解一下虚拟文件系统的四大对象、</p><h2 id="一、minix文件系统" tabindex="-1">一、MINIX文件系统 <a class="header-anchor" href="#一、minix文件系统" aria-label="Permalink to &quot;一、MINIX文件系统&quot;">​</a></h2><p>这部分是在参考<a href="https://github.com/sumumm/linux-0.12/blob/master/docs/%E7%AC%AC12%E7%AB%A0-%E6%96%87%E4%BB%B6%E7%B3%BB%E7%BB%9F/%E7%AC%AC12%E7%AB%A0-%E6%96%87%E4%BB%B6%E7%B3%BB%E7%BB%9F.md" target="_blank" rel="noreferrer">linux-0.12/docs/第12章-文件系统/第12章-文件系统.md at master · sumumm/linux-0.12 · GitHub</a>，它是以minix文件系统来讲述的。先来简单了解一下这个文件系统。</p><img src="'+r+'" alt="1531300792461.png"><p>如图所示，整个磁盘设备被分为以1kb为单位的磁盘块，上图中的每一方格表示一磁盘块（i节点块数可变）。</p><div class="language-txt vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MINIX1.0=inode结点+inode结点位图+磁盘块+磁盘块位图+超级块+引导块</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>引导扇区（boot sector）安装于硬盘的第一个扇区。引导块（boot block）包含一个非常小的引导记录和一个分区表。引导扇区本身512B，但是为了块对齐占用一块磁盘块也就是1KB。</li><li>每一个分区中的第一个块是超级块（superblock），它包含了定义其他文件系统结构的元数据，并将它们定位在分配给分区的物理磁盘上。占用一个磁盘块，每个超级块占用14字节。</li><li>节点位图块（inode bitmap block），它确定了哪个节点在使用以及哪个节点是空闲的。</li><li>节点（inodes），它们在磁盘上有它们自己的空间。每个节点包含了一个文件的信息，包括数据块的位置，即文件所属的区域。一个磁盘块可以表示1024*8=8192个i节点的使用情况。每个位代表一个磁盘块是否被占用。</li><li>区域位图（zone bitmap）跟踪记录数据区域的使用和释放。</li><li>数据区域（data zone），数据实际上存储的位置。</li><li>对于位图的两个类型来说，一个bit代表了一个特有的数据区域或者一个特有的节点。如果这个bit是0，这个区域或者节点是空闲的而且可供使用，但是如果这个bit是1，这个数据区域或者节点是在使用中的。</li><li>节点是什么？它是索引节点（index-node）的缩写，一个节点是在磁盘上的一个256字节的块，而且它存储文件相关的数据。这些数据包括文件的大小；文件的用户和所属组的用户ID；文件模式（即访问权限）；以及三个时间戳具体说明了时间，包括：文件最后访问时间，最后修改时间，以及节点中的数据最后修改时间。节点也包含了：指向硬盘上文件数据所在的位置。在Minix和EXT1-3文件系统中，它是一个数据区域和块的列表。Minix文件系统节点支持9个数据块，7个直接指针和2个间接指针。</li></ul><h2 id="二、linux虚拟文件系统的四大对象" tabindex="-1">二、Linux虚拟文件系统的四大对象 <a class="header-anchor" href="#二、linux虚拟文件系统的四大对象" aria-label="Permalink to &quot;二、Linux虚拟文件系统的四大对象&quot;">​</a></h2><h3 id="_1-回顾一下" tabindex="-1">1. 回顾一下 <a class="header-anchor" href="#_1-回顾一下" aria-label="Permalink to &quot;1. 回顾一下&quot;">​</a></h3><p>Linux为了对超级块，i节点，逻辑块这三部分进行高效的管理，Linux创建了几种不同的数据结构，分别是<strong>超级块、索引节点inode、目录项dentry</strong>等几种。再加上文件对象(file)，就构成了VFS的四大对象。</p><h3 id="_2-超级块-super-block" tabindex="-1">2. 超级块(super block) <a class="header-anchor" href="#_2-超级块-super-block" aria-label="Permalink to &quot;2. 超级块(super block)&quot;">​</a></h3><p>一个超级块对应一个文件系统(已经安装的文件系统类型，如ext2，此处是实际的文件系统，不是VFS)。之前我们已经了解了文件系统用于管理文件的数据格式和操作之类的，系统文件有系统文件自己的文件系统，同时对于不同的磁盘分区也有可以是不同的文件系统。那么一个超级块对于一个独立的文件系统。保存文件系统的类型、大小、状态等等。</p><blockquote><p>Tips：</p><p>“文件系统”和“文件系统类型”不一样！一个文件系统类型下可以包括很多文件系统，即很多的super_block。</p></blockquote><p>超级块反映了文件系统整体的控制信息。例如：硬盘分区中每个block的大小、硬盘分区上一共有多少个block group、以及每个block group中有多少个inode。</p><p>超级块能够以多种的方式存在，对于基于磁盘的文件系统，它以特定的格式存在于磁盘的固定区域（取决于文件系统类型）上。在挂载文件系统时，该超级块中的内容被读入磁盘中，从而构建出位于内存中的新的超级块。</p><blockquote><p><a href="https://git.kernel.org/pub/scm/linux/kernel/git/stable/linux.git/tree/include/linux/fs.h?h=linux-4.19.y&amp;id=e7d2672c66e4d3675570369bf20856296da312c4#n1369" target="_blank" rel="noreferrer">fs.h « linux « include - <em>struct super_block</em></a></p></blockquote><h3 id="_3-索引节点inode" tabindex="-1">3. 索引节点inode <a class="header-anchor" href="#_3-索引节点inode" aria-label="Permalink to &quot;3. 索引节点inode&quot;">​</a></h3><p>索引节点inode则反映了文件系统对象中的一般元数据信息。</p><p>文件一般是由 inode 以及 inode指向的数据块构成，Inode记录了文件的管理信息，数据块记录文件的具体内容。</p><p>目录也是由 inode 以及inode指向的数据块构成 ，但目录的数据块 记录的是该目录下的 子目录/文件的 inode 以及 子目录名/文件名 等信息。</p><blockquote><p><a href="https://git.kernel.org/pub/scm/linux/kernel/git/stable/linux.git/tree/include/linux/fs.h?h=linux-4.19.y&amp;id=e7d2672c66e4d3675570369bf20856296da312c4#n593" target="_blank" rel="noreferrer">fs.h « linux « include - <em>struct inode</em></a></p></blockquote><h3 id="_4-目录项dentry" tabindex="-1">4. 目录项dentry <a class="header-anchor" href="#_4-目录项dentry" aria-label="Permalink to &quot;4. 目录项dentry&quot;">​</a></h3><p>目录项dentry则是反映出某个文件系统对象在全局文件系统树中的位置。dentry中包含了文件名，文件的inode号等信息。</p><p>它只存在于内存中，更确切的说是存在于内存的目录项缓存，为了提高查找性能而设计。注意不管是文件夹还是最终的文件，都是属于目录项，所有的目录项在一起构成一颗庞大的目录树。例如：open一个文件 /home/xxx/yyy.txt ，那么 /、home、xxx、yyy.txt 都是一个目录项，VFS在查找的时候，根据一层一层的目录项找到对应的每个目录项的inode，那么沿着目录项进行操作就可以找到最终的文件。</p><p>dentry结构是一种含有指向父节点和子节点指针的双向结构，多个这样的双向结构构成一个内存里面的树状结构，也就是文件系统的目录结构在内存中的缓存了。有了这个缓存，我们在访问文件系统时，通常都非常快捷。</p><blockquote><p>Tips</p><p><strong>目录也是一种文件(所以也存在对应的inode)</strong>。打开目录，实际上就是打开目录文件。</p></blockquote><p>举个文件的例子：/home/user/Desktop/a.txt ，假设 a.txt和 / 在同一个文件系统，那么，只需要读 / inode读到 home并找到找到home 的inode 并读取，这样步步跳转，最后会读取a.txt这文件对应的 inode，好了，我们打开 a.txt 这个文件并读取内容 时，VFS会调用 ext3 的 read() 去 读此inode对应的数据块。</p><blockquote><p><a href="https://git.kernel.org/pub/scm/linux/kernel/git/stable/linux.git/tree/include/linux/dcache.h?h=linux-4.19.y&amp;id=e7d2672c66e4d3675570369bf20856296da312c4#n88" target="_blank" rel="noreferrer">dcache.h « linux « include - <em>struct dentry</em></a></p></blockquote><h3 id="_5-文件对象file" tabindex="-1">5. 文件对象file <a class="header-anchor" href="#_5-文件对象file" aria-label="Permalink to &quot;5. 文件对象file&quot;">​</a></h3><p>注意文件对象描述的是进程已经打开的文件。因为一个文件可以被多个进程打开，所以一个文件可以存在多个文件对象。但是由于文件是唯一的，那么inode就是唯一的，目录项也是定的！</p><p>进程其实是通过文件描述符来操作文件的，注意每个文件都有一个32位的数字来表示下一个读写的字节位置，这个数字叫做文件位置。一般情况下打开文件后，打开位置都是从0开始，除非一些特殊情况。Linux用file结构体来保存打开的文件的位置，所以file称为打开的文件描述。file结构形成一个双链表，称为<strong>系统打开文件表</strong>。</p><blockquote><p><a href="https://git.kernel.org/pub/scm/linux/kernel/git/stable/linux.git/tree/include/linux/fs.h?h=linux-4.19.y&amp;id=e7d2672c66e4d3675570369bf20856296da312c4#n891" target="_blank" rel="noreferrer">fs.h « linux « include - <em>struct file</em></a></p></blockquote><p>file只是对一个文件而言，对于一个进程(用户)来说，可以同时处理多个文件，所以需要另一个结构来管理所有的files</p><blockquote><p><a href="https://git.kernel.org/pub/scm/linux/kernel/git/stable/linux.git/tree/include/linux/fdtable.h?h=linux-4.19.y&amp;id=e7d2672c66e4d3675570369bf20856296da312c4#n48" target="_blank" rel="noreferrer">fdtable.h « linux « include - <em>struct files_struct</em></a></p></blockquote><p>上面的file和files_struct记录的是与进程相关的文件的信息，但是对于进程本身来说，自身的一些信息用什么表示，这里就涉及到fs_struct结构体。</p><blockquote><p><a href="https://git.kernel.org/pub/scm/linux/kernel/git/stable/linux.git/tree/include/linux/fs_struct.h?h=linux-4.19.y&amp;id=e7d2672c66e4d3675570369bf20856296da312c4#n9" target="_blank" rel="noreferrer">fs_struct.h « linux « include - <em>struct fs_struct</em></a></p></blockquote><h2 id="三、进程与这四大对象的关系" tabindex="-1">三、进程与这四大对象的关系 <a class="header-anchor" href="#三、进程与这四大对象的关系" aria-label="Permalink to &quot;三、进程与这四大对象的关系&quot;">​</a></h2><p>内核中用于管理进程的结构体是task_struct。进程打开文件就涉及到上述4个重要的数据结构:</p><img src="'+a+'" alt="image-20241224225509388"><blockquote><p>Tips：f_dentry is gone; use f_path.dentry。</p><p>在这里有说明<a href="https://git.kernel.org/pub/scm/linux/kernel/git/stable/linux.git/tree/Documentation/filesystems/porting?h=linux-4.19.y&amp;id=e7d2672c66e4d3675570369bf20856296da312c4#n472" target="_blank" rel="noreferrer">porting « filesystems « Documentation - kernel/git/stable/linux.git - Linux kernel stable tree</a></p></blockquote><p>每个进程都有自己的namespace。fs_struct用于表示进程与文件系统之间的结构关系，比如当前的工作目录，进程的根目录等等。files_struct 用于表示当前进程打开的文件。而对于每一个打开的文件，由file对象来表示。</p><p>Linux中，常常用文件描述符(file descriptor)来表示一个打开的文件，这个描述符的值往往是一个大于或等于0的整数。而这个整数,其实就是在files_struct中file数组fd_array的下标。对于所有打开的文件, 这些文件描述符会存储在open_fds的位图中。</p><p>从图中可以看出：</p><p>（1）进程通过task_struct中的一个域files→files_struct 来了解它当前所打开的文件对象；而我们通常所说的文件描述符其实是进程打开的文件对象数组的索引值。</p><p>（2）文件对象通过域f_path.dentry找到它对应的dentry对象，再由dentry对象的域d_inode找到它对应的索引节点（通过索引节点又可以得到超级块的信息，也就可以得到最终操作文件的方法，在open文件的时候就是使用这样一个过程），这样就建立了文件对象与实际的物理文件的关联。</p><p>（3）文件对象所对应的文件操作函数列表是通过索引节点的域i_fop得到的，而i_fop最终又是通过struct super_operations *s_op来初始化的。</p><p>VFS文件系统中的inode和dentry与实际文件系统的inode和dentry有一定的关系，但不能等同。</p><p>真实磁盘文件的inode和dentry是存在于物理外存上的，但VFS中的inode和dentry是存在于内存中的，系统读取外存中的inode和dentry信息进行一定加工后，生成内存中的inode和dentry。</p><p>虚拟的文件系统也具有inode和dentry结构，只是这是系统根据相应的规则生成的，不存在于实际外存中。</p><blockquote><p>参考资料：</p><p>【1】<a href="https://www.cnblogs.com/yikoulinux/p/14470713.html" target="_blank" rel="noreferrer">Linux 虚拟文件系统四大对象：超级块、inode、dentry、file之间关系 - 一口Linux - 博客园</a></p><p>【2】<a href="https://github.com/0voice/linux_kernel_wiki/blob/main/%E6%96%87%E7%AB%A0/%E6%96%87%E4%BB%B6%E7%B3%BB%E7%BB%9F/%E8%99%9A%E6%8B%9F%E6%96%87%E4%BB%B6%E7%B3%BB%E7%BB%9F.md" target="_blank" rel="noreferrer">linux_kernel_wiki/文章/文件系统/虚拟文件系统.md at main · 0voice/linux_kernel_wiki · GitHub</a></p><p>【3】<a href="https://blog.csdn.net/gitblog_09759/article/details/141970656" target="_blank" rel="noreferrer">Linux内核完全注释(修正版v5.0)-CSDN博客</a></p><p>【4】<a href="https://www.cnblogs.com/bandaoyu/p/16752004.html" target="_blank" rel="noreferrer">【文件】VFS四大struct:file、dentry、inode、super_block 是什么？区别？关系?--编辑中 - bdy - 博客园</a></p></blockquote>',51)])])}const m=t(o,[["render",d]]);export{f as __pageData,m as default};
